export const scenarioCatalog: ScenarioCase[] = definitions.map(
  ([id, fr, ac, baseline, action, expected]) => ({
    id,
    requirements: fr.split(' ').filter(Boolean),
    acceptance: ac.split(' ').filter(Boolean),
    baseline,
    action,
    expected,
    source:
      Number(id.slice(3)) >= 33 && (Number(id.slice(3)) <= 40 || ['SC-043', 'SC-044'].includes(id))
        ? 'tests/scenarios/http.test.ts'
        : 'tests/scenarios/business.test.ts',
  }),
);
